using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;

/// <summary>
/// Background music: a shuffled playlist of the calm loops in Resources/Music (cozy city-builder / space-agency mood), cross-faded.
/// Created automatically when the game starts and kept between scenes. M mutes / unmutes. Every track is generated by
/// ArtSource/make_music.py, so there is no third-party licence to worry about.
/// </summary>
public class MusicPlayer : MonoBehaviour
{
    const string VolumeKey = "SpaceAgency.MusicVolume", MuteKey = "SpaceAgency.MusicMuted";
    public static MusicPlayer Instance { get; private set; }

    [Range(0f, 1f)] public float volume = 0.55f;
    public float crossfadeSeconds = 4f;

    AudioSource[] sources;
    int active;
    readonly List<AudioClip> order = new List<AudioClip>();
    int next;
    bool muted;
    float master = 1f;                                   // 0..1, eased towards the mute state

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
    static void Boot()
    {
        if (Instance != null) return;
        var clips = Resources.LoadAll<AudioClip>("Music");
        if (clips == null || clips.Length == 0) return;
        var go = new GameObject("Music Player");
        DontDestroyOnLoad(go);
        go.AddComponent<MusicPlayer>();
    }

    void Awake()
    {
        if (Instance != null) { Destroy(gameObject); return; }
        Instance = this;
        volume = PlayerPrefs.GetFloat(VolumeKey, volume);
        muted = PlayerPrefs.GetInt(MuteKey, 0) == 1;
        master = muted ? 0f : 1f;
        sources = new AudioSource[2];
        for (int i = 0; i < 2; i++)
        {
            var s = gameObject.AddComponent<AudioSource>();
            s.playOnAwake = false; s.loop = false; s.spatialBlend = 0f; s.volume = 0f; s.ignoreListenerPause = true;
            sources[i] = s;
        }
        if (FindAnyObjectByType<AudioListener>() == null && Camera.main != null) Camera.main.gameObject.AddComponent<AudioListener>();
        Reshuffle(null);
        StartCoroutine(Run());
    }

    void Reshuffle(AudioClip notFirst)
    {
        order.Clear();
        order.AddRange(Resources.LoadAll<AudioClip>("Music"));
        for (int i = order.Count - 1; i > 0; i--) { int j = Random.Range(0, i + 1); (order[i], order[j]) = (order[j], order[i]); }
        if (notFirst != null && order.Count > 1 && order[0] == notFirst) (order[0], order[order.Count - 1]) = (order[order.Count - 1], order[0]);
        next = 0;
    }

    IEnumerator Run()
    {
        while (order.Count > 0)
        {
            if (next >= order.Count) Reshuffle(order[order.Count - 1]);
            var clip = order[next++];
            var from = sources[active];
            active = 1 - active;
            var to = sources[active];
            to.clip = clip; to.time = 0f; to.volume = 0f; to.Play();
            // fade this track in while the previous one fades out
            for (float t = 0f; t < crossfadeSeconds; t += Time.unscaledDeltaTime)
            {
                float k = Mathf.Clamp01(t / crossfadeSeconds);
                to.volume = k * volume * master; from.volume = (1f - k) * volume * master;
                yield return null;
            }
            from.Stop();
            // play until the crossfade point of the next track
            while (to.isPlaying && to.time < clip.length - crossfadeSeconds) { to.volume = volume * master; yield return null; }
        }
    }

    void Update()
    {
        var kb = Keyboard.current;
        if (kb != null && kb.mKey.wasPressedThisFrame)
        {
            muted = !muted;
            PlayerPrefs.SetInt(MuteKey, muted ? 1 : 0);
            Hud.Toast(muted ? "Music off (press M to turn it on)" : "Music on");
        }
        master = Mathf.MoveTowards(master, muted ? 0f : 1f, Time.unscaledDeltaTime * 2f);
    }

    public void SetVolume(float v) { volume = Mathf.Clamp01(v); PlayerPrefs.SetFloat(VolumeKey, volume); }
}
